const $=s=>document.querySelector(s),toast=$('#toast');
const pageAdSlots=[['home','Iklan beranda setelah katalog','728x90'],['detail','Iklan detail mod','728x90'],['top','Iklan atas','728x90'],['inline1','Iklan artikel 1','300x250'],['inline2','Iklan artikel 2','300x250'],['bottom','Iklan bawah','728x90']],allAdSlots=['left','right',...pageAdSlots.map(x=>x[0])];
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>toast.classList.remove('show'),3200)}
function pageAdField([slot,title,defaultSize]){const sizes=['970x90','728x90','468x60','320x50','300x250'];return `<fieldset><legend>${title}</legend><label>Jenis iklan<select id="ad-${slot}-mode"><option value="banner">Banner gambar</option><option value="code">Kode jaringan iklan</option></select></label><label>Ukuran<select id="ad-${slot}-size">${sizes.map(size=>`<option value="${size}" ${size===defaultSize?'selected':''}>${size.replace('x',' × ')}</option>`).join('')}</select></label><label>Label<input id="ad-${slot}-label" maxlength="40"></label><div class="ad-banner-fields" data-ad-banner="${slot}"><label>URL gambar<input id="ad-${slot}-image" type="url" placeholder="https://.../banner.jpg"></label><label>Link tujuan<input id="ad-${slot}-url" type="url" placeholder="https://..."></label></div><label class="ad-code-field" data-ad-code="${slot}">Kode HTML / JavaScript<textarea id="ad-${slot}-code" rows="5" spellcheck="false" placeholder="Tempel kode unit iklan"></textarea></label><label class="switch-row"><span><b>Aktifkan posisi ini</b></span><input id="ad-${slot}-active" type="checkbox"></label></fieldset>`}
$('#download-ad-fields').innerHTML=pageAdSlots.map(pageAdField).join('');
function updateAdFields(slot){const mode=$(`#ad-${slot}-mode`).value;document.querySelector(`[data-ad-banner="${slot}"]`).hidden=mode!=='banner';document.querySelector(`[data-ad-code="${slot}"]`).hidden=mode!=='code'}
let loadedSettings={};
async function loadAds(){loadedSettings=await NMData.getSettings();$('#download-click-url').value=loadedSettings.downloadClickAd?.url||'';$('#download-click-active').checked=Boolean(loadedSettings.downloadClickAd?.active);const ads=loadedSettings.ads;allAdSlots.forEach(slot=>{const data=ads?.[slot]||{};$(`#ad-${slot}-mode`).value=data.mode==='code'?'code':'banner';if(data.size)$(`#ad-${slot}-size`).value=data.size;$(`#ad-${slot}-label`).value=data.label||'';$(`#ad-${slot}-image`).value=data.image||'';$(`#ad-${slot}-url`).value=data.url||'';$(`#ad-${slot}-code`).value=data.code||'';$(`#ad-${slot}-active`).checked=Boolean(data.active);updateAdFields(slot)})}
allAdSlots.forEach(slot=>$(`#ad-${slot}-mode`).addEventListener('change',()=>updateAdFields(slot)));
$('#ad-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter,ad=slot=>({mode:$(`#ad-${slot}-mode`).value,size:$(`#ad-${slot}-size`).value,label:$(`#ad-${slot}-label`).value.trim(),image:$(`#ad-${slot}-image`).value.trim(),url:$(`#ad-${slot}-url`).value.trim(),code:$(`#ad-${slot}-code`).value.trim(),active:$(`#ad-${slot}-active`).checked});button.disabled=true;button.textContent='Menyimpan…';try{const url=$('#download-click-url').value.trim(),active=$('#download-click-active').checked;if(url){let parsed;try{parsed=new URL(url)}catch{throw new Error('Masukkan URL iklan HTTPS yang valid.')}if(parsed.protocol!=='https:'||parsed.username||parsed.password)throw new Error('Gunakan URL HTTPS tanpa informasi login.')}if(active&&!url)throw new Error('Isi URL Smartlink sebelum mengaktifkan iklan.');await NMData.saveSettings({...loadedSettings,downloadClickAd:{active,url},ads:Object.fromEntries(allAdSlots.map(slot=>[slot,ad(slot)]))});notify('Pengaturan monetisasi tersimpan online.')}catch(error){notify(error.message||'Pengaturan gagal disimpan.')}finally{button.disabled=false;button.innerHTML='Simpan semua pengaturan <span>→</span>'}});
(async()=>{try{if(!await NMData.isAdmin())return location.replace('admin.html');await loadAds()}catch{return location.replace('admin.html')}})();
